// Post a message to a Discord channel via the bot, then record a note.
// Executor wraps this body as (async (args, context) => { <code> }); use args
// directly and `return` the result. callProvider(tool, method, path, body?)
// runs the required tool through the dispatcher (resolves the tool by NAME
// 'discord_bot', injects the vaulted bot token as Authorization: Bot <token>,
// uses the tool's config.baseUrl = https://discord.com/api/v10).
const content = String(args?.content ?? '').trim();
if (!content) throw new Error('discord_send_message: content is required');
const channelId = String(args?.channelId ?? '{{channelId}}').trim();
if (!channelId) throw new Error('discord_send_message: channelId is required (pass it or set a default in the template)');

// Discord v10 create-message endpoint.
const res = await callProvider('discord_bot', 'POST', '/channels/' + encodeURIComponent(channelId) + '/messages', { content });
const ok = res?.status ? res.status >= 200 && res.status < 300 : true;
const payload = res?.body ?? res;
const messageId = payload?.id ?? null;

await propose.entity({
  profileSlug: 'note',
  title: 'Discord message ' + (ok ? 'sent' : 'attempted') + ' -> #' + channelId,
  properties: {
    action: 'discord_send_message',
    channelId: channelId,
    content: content,
    messageId: messageId,
    status: res?.status ?? null,
    success: ok,
    source: 'discord-bot'
  },
  reasoning: 'Recorded the outbound Discord message for the activity timeline.'
});
return { success: ok, channelId: channelId, messageId: messageId, status: res?.status ?? null };
